<?php
namespace App\Http\Controllers\Api;
use App\Actions\Orders\RefundOrder; use App\Enums\PaymentMethod; use App\Enums\PaymentStatus; use App\Http\Requests\Api\RefundPaymentRequest; use App\Http\Resources\PaymentResource; use App\Models\Order; use App\Models\Payment; use App\Models\User; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\Validation\Rule; use Illuminate\Validation\ValidationException;
/** @group Payments */ class PaymentController extends ApiController {
public function store(Request $r,Order $order):JsonResponse{$this->own($r,$order);$v=$r->validate(['method'=>['required',Rule::enum(PaymentMethod::class)],'amount'=>['required','integer','min:0'],'received_amount'=>['required','integer','min:0'],'reference_number'=>['nullable','string','max:100']]);if($order->payment)throw ValidationException::withMessages(['payment'=>'Order sudah memiliki pembayaran.']);if($v['amount']!==$order->grand_total)throw ValidationException::withMessages(['amount'=>'Amount harus sama dengan total order.']);$m=PaymentMethod::from($v['method']);if($m===PaymentMethod::CASH&&$v['received_amount']<$v['amount'])throw ValidationException::withMessages(['received_amount'=>'Uang diterima kurang.']);$p=$order->payment()->create(['idempotency_key'=>(string)Str::uuid(),'method'=>$m,'status'=>PaymentStatus::PAID,'amount'=>$v['amount'],'received_amount'=>$m===PaymentMethod::CASH?$v['received_amount']:$v['amount'],'change_amount'=>$m===PaymentMethod::CASH?max(0,$v['received_amount']-$v['amount']):0,'reference_number'=>$v['reference_number']??null,'paid_at'=>now(),'created_by'=>$r->user()->id]);return $this->success(new PaymentResource($p),'Pembayaran dicatat.',201);}
public function index(Request $r,Order $order):JsonResponse{$this->own($r,$order);return $this->success(PaymentResource::collection(Payment::where('order_id',$order->id)->get()));}
public function refund(RefundPaymentRequest $r,Payment $payment,RefundOrder $a):JsonResponse{$this->own($r,$payment->order);$m=User::findOrFail($r->integer('approved_by'));$o=$a->handle($payment->order,$r->user(),$m,$r->string('pin'),$r->string('reason'),$r->boolean('restock',true));return $this->success(new PaymentResource($o->payment),'Pembayaran direfund.');}
private function own(Request $r,Order $o):void{abort_unless($o->cashier_id===$r->user()->id||$r->user()->hasRole('OWNER','MANAGER'),403);}}
